 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(marks) != 2:
        return [row[:] for row in grid]

    # Move the lower marker's associated pattern by the displacement from
    # the lower marker to the upper marker; leave the source pattern intact.
    (upper_r, upper_c), (lower_r, lower_c) = marks
    dr, dc = upper_r - lower_r, upper_c - lower_c
    out = [row[:] for row in grid]
    out[upper_r][upper_c] = 0
    for r in range(lower_r + 1, h):
        for c, value in enumerate(grid[r]):
            if value:
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = value
    return out
